"""CRUD endpoints for owners."""

from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, Query, Response, status
from sqlalchemy import select
from sqlalchemy.orm import Session

from app.db import get_session
from app.models import Owner
from app.schemas import OwnerCreate, OwnerRead, OwnerUpdate

router = APIRouter(prefix="/owners", tags=["owners"])
SessionDep = Annotated[Session, Depends(get_session)]


def _get_or_404(session: Session, owner_id: int) -> Owner:
    owner = session.get(Owner, owner_id)
    if owner is None:
        raise HTTPException(status.HTTP_404_NOT_FOUND, detail="Owner not found")
    return owner


@router.get("", response_model=list[OwnerRead])
def list_owners(
    session: SessionDep,
    limit: Annotated[int, Query(ge=1, le=200)] = 50,
    offset: Annotated[int, Query(ge=0)] = 0,
) -> list[Owner]:
    query = select(Owner).order_by(Owner.id)
    return list(session.scalars(query.offset(offset).limit(limit)))


@router.post("", response_model=OwnerRead, status_code=status.HTTP_201_CREATED)
def create_owner(payload: OwnerCreate, session: SessionDep) -> Owner:
    owner = Owner(**payload.model_dump())
    session.add(owner)
    session.commit()
    session.refresh(owner)
    return owner


@router.get("/{owner_id}", response_model=OwnerRead)
def get_owner(owner_id: int, session: SessionDep) -> Owner:
    return _get_or_404(session, owner_id)


@router.patch("/{owner_id}", response_model=OwnerRead)
def update_owner(
    owner_id: int,
    payload: OwnerUpdate,
    session: SessionDep,
) -> Owner:
    owner = _get_or_404(session, owner_id)
    for key, value in payload.model_dump(exclude_unset=True).items():
        setattr(owner, key, value)
    session.commit()
    session.refresh(owner)
    return owner


@router.delete("/{owner_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_owner(owner_id: int, session: SessionDep) -> Response:
    session.delete(_get_or_404(session, owner_id))
    session.commit()
    return Response(status_code=status.HTTP_204_NO_CONTENT)

"""CRUD endpoints for pets."""

from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, Query, Response, status
from sqlalchemy import select
from sqlalchemy.orm import Session

from app.db import get_session
from app.models import Owner, Pet
from app.schemas import PetCreate, PetRead, PetUpdate

router = APIRouter(prefix="/pets", tags=["pets"])
SessionDep = Annotated[Session, Depends(get_session)]


def _get_or_404(session: Session, pet_id: int) -> Pet:
    pet = session.get(Pet, pet_id)
    if pet is None:
        raise HTTPException(status.HTTP_404_NOT_FOUND, detail="Pet not found")
    return pet


def _check_parents(
    session: Session,
    owner_id: int | None,
) -> None:
    """A pet must point at an owner that exist."""
    if owner_id is not None and session.get(Owner, owner_id) is None:
        raise HTTPException(422, detail=f"Owner {owner_id} not found")


@router.get("", response_model=list[PetRead])
def list_pets(
    session: SessionDep,
    limit: Annotated[int, Query(ge=1, le=200)] = 50,
    offset: Annotated[int, Query(ge=0)] = 0,
    owner_id: Annotated[int | None, Query(gt=0)] = None,
) -> list[Pet]:
    query = select(Pet).order_by(Pet.id)
    if owner_id is not None:
        query = query.where(Pet.owner_id == owner_id)
    return list(session.scalars(query.offset(offset).limit(limit)))


@router.post("", response_model=PetRead, status_code=status.HTTP_201_CREATED)
def create_pet(payload: PetCreate, session: SessionDep) -> Pet:
    _check_parents(session, payload.owner_id)
    pet = Pet(**payload.model_dump())
    session.add(pet)
    session.commit()
    session.refresh(pet)
    return pet


@router.get("/{pet_id}", response_model=PetRead)
def get_pet(pet_id: int, session: SessionDep) -> Pet:
    return _get_or_404(session, pet_id)


@router.patch("/{pet_id}", response_model=PetRead)
def update_pet(
    pet_id: int,
    payload: PetUpdate,
    session: SessionDep,
) -> Pet:
    pet = _get_or_404(session, pet_id)
    _check_parents(session, payload.owner_id)
    for key, value in payload.model_dump(exclude_unset=True).items():
        setattr(pet, key, value)
    session.commit()
    session.refresh(pet)
    return pet


@router.delete("/{pet_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_pet(pet_id: int, session: SessionDep) -> Response:
    session.delete(_get_or_404(session, pet_id))
    session.commit()
    return Response(status_code=status.HTTP_204_NO_CONTENT)

